/** @typedef {import("./EffectProfileHalfLife").default} EffectProfileHalfLife */
/** @typedef {import("./Time").default} Time */

import EffectProfileHalfLife from './EffectProfileHalfLife.js'
import DateTimeRange from './DateTimeRange.js'

export default class EffectProfile extends DateTimeRange {
  /**
   * @param {Object} options
   * @param {string} options.name
   * @param {[EffectProfileHalfLife]} options.halfLifes
   */
  constructor ({ name, halfLifes }) {
    halfLifes = halfLifes.map(hl => new EffectProfileHalfLife(hl))
    const first = halfLifes[0]
    const last = halfLifes[halfLifes.length - 1]
    const startMs = first.startMs
    const endMs = last.endMs
    super({
      startMs,
      endMs
    })
    this.halfLifes = halfLifes
    this.name = name
  }

  set name (value) {
    this._name = value
  }

  /** @type {[string]} */
  get name () {
    return this._name
  }

  set halfLifes (value) {
    this._halfLifes = value
  }

  /** @type {[EffectProfileHalfLife]} */
  get halfLifes () {
    return this._halfLifes
  }

  /** @type {EffectProfileHalfLife} */
  get lastHalfLife () {
    return this._halfLifes[this.halfLifes.length - 1]
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getRemainingIntensityAt ({ ms }) {
    return this.halfLifes.reduce((intensity, halfLife) => {
      return intensity + (halfLife.getRemainingIntensityAt({ ms }) * halfLife.partRatio)
    }, 0)
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getPassedIntensityAt ({ ms }) {
    return this.halfLifes.reduce((intensity, halfLife) => {
      return intensity + (halfLife.getPassedIntensityAt({ ms }) * halfLife.partRatio)
    }, 0)
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getIntensityAt ({ ms }) {
    return this.halfLifes.reduce((intensity, halfLife) => {
      return intensity + (halfLife.getIntensityAt({ ms }) * halfLife.partRatio)
    }, 0)
  }

  /** @type {number} */
  get peakEnd () {
    const last = this.lastHalfLife
    // leaves 1/8th left into the slow slope, out of the peak
    // peakMs = 1/2, peakMs + halfLife = 1/4, peak + 2(halflife) = 1/8
    const peakEnd = last.startMs + last.peakMs + (last.halfLifeMs * 2)
    return peakEnd
  }
}
