import BgUnitEffects from './BgUnitEffects.js'
import BolusEffects from './BolusEffects.js'
import BolusUnits from './BolusUnits.js'
import EfficacyRatio from './EfficacyRatio.js'
import CarbEffects from './CarbEffects.js'
import CarbUnitEffects from './CarbUnitEffects.js'
import Effects from './Effects.js'
import MixedUnitEffects from './MixedUnitEffects.js'
import CarbAmount from './CarbAmount.js'
import Time from './Time.js'
import BasalRange from './BasalRange.js'
import BasalUnits from './BasalUnits.js'
import { mean } from './utils.js'

/** @typedef {import("./Effects").default} Effects */

export default class Analysis extends Effects {
  /**
   * @param {Object} options
   * @param {Timeline} options.timeline
   * @param {[Effects]} options.items
   */
  constructor ({ timeline, items, minimumDurationHHmm } = {}) {
    super({ timeline, items })
    this.minimumDurationMs = Time.fromHHmm(minimumDurationHHmm)
  }

  set minimumDurationMs (value) {
    this._minimumDurationMs = value
  }

  get minimumDurationMs () {
    return this._minimumDurationMs
  }

  get filteredItems () {
    return this.items
      .filter(br => br instanceof BasalRange && br.durationMs >= this.minimumDurationMs)
  }

  get configuredUnitsPerDose () {
    const unitsPerDoses = this
      .filteredItems
      .map(basalRange => basalRange.configuredUnitsPerDose)
    return mean(unitsPerDoses)
  }

  calculateBgPerHour () {
    const items = this.filteredItems
    if (!items.length) return 0
    const bgPerHour = items.reduce((sum, basalRange) => sum + basalRange.bgPerHour, 0) / items.length
    return bgPerHour
  }

  calculateUnitsPerDose () {
    const doses = this
      .filteredItems
      .map(basalRange => {
        const adjustmentRatio = this.calculateAdjustmentRatio({ bgPerHour: basalRange.bgPerHour })
        const currentDose = basalRange.configuredUnitsPerDose
        return currentDose + (currentDose * adjustmentRatio)
      })
    return mean(doses)
  }

  calculateAdjustmentRatio () {
    const ratios = this
      .filteredItems
      .map(basalRange => {
        return this.calculateAdjustmentRatio({
          bgPerHour: basalRange.bgPerHour
        })
      })
    return mean(ratios)
  }

  static calculateAdjustmentRatio ({ bgPerHour }) {
    const rads = Math.atan(bgPerHour)
    const degs = rads * 180 / Math.PI
    if (degs > 0) return (degs / 90)
    return (degs / 90) / 2
  }

  getBasalAt ({ ms }) {
    return this.getAmountAt({ ms, classRef: BasalUnits })
  }

  /** @type {[BolusEffects]} */
  get isolatedItems () {
    return this.items.filter(b => b instanceof BolusEffects && b.hasIsolatedEffect)
  }

  /** @type {[BolusEffects]} */
  get bgPerUnitEffects () {
    return this
      .isolatedItems
      .filter(e =>
        e instanceof BgUnitEffects ||
        (e instanceof MixedUnitEffects && e.isCarbUnitsLessThanMinimumUnits)
      )
  }

  /** @type {number} */
  get configuredBgPerUnit () {
    const { bgPerUnitEffects } = this
    const bgPerUnits = bgPerUnitEffects.map(bolusEffect => bolusEffect.configuredBgPerUnit).filter(Boolean)
    return mean(bgPerUnits)
  }

  /**
   * @returns {number}
   */
  calculateBgPerUnit () {
    const bgPerUnits = this.bgPerUnitEffects
      .filter(bolusEffect => bolusEffect.bgUnitsTaken)
      .filter(bolusEffect => bolusEffect.isEndBgAfterPeak && !bolusEffect.hasOverlappingEffects)
      .map(bolusEffect => bolusEffect.calculateBgPerUnit())
    return mean(bgPerUnits)
  }

  /** @type {[CarbEffects]} */
  get bgPerCarbEffects () {
    return this
      .isolatedItems
      .filter(e => e instanceof CarbEffects)
  }

  /** @type {number} */
  get configuredBgPerCarb () {
    const { configuredBgPerUnit, configuredCarbsPerUnit } = this
    return (configuredBgPerUnit * -1) / configuredCarbsPerUnit
  }

  /**
   * @returns {number}
   */
  calculateBgPerCarb () {
    const { bgPerCarbEffects } = this
    const carbsPerBgs = bgPerCarbEffects.map(bolusEffect => bolusEffect.calculateBgPerCarb())
    return mean(carbsPerBgs)
  }

  /** @type {[Effects]} */
  get carbsPerUnitEffects () {
    return this
      .isolatedItems
      .filter(e =>
        e instanceof CarbUnitEffects ||
        (e instanceof MixedUnitEffects && e.isBgUnitsLessThanMinimumUnits)
      )
  }

  /** @type {number} */
  get configuredCarbsPerUnit () {
    const { carbsPerUnitEffects } = this
    const carbsPerUnits = carbsPerUnitEffects.map(bolusEffect => bolusEffect.configuredCarbsPerUnit).filter(Boolean)
    return mean(carbsPerUnits)
  }

  /**
   * @param {Object} options
   * @param {number} options.bgPerUnit
   * @returns {number}
   */
  calculateCarbsPerUnit ({ bgPerUnit }) {
    const { carbsPerUnitEffects } = this
    const carbsPerUnits = carbsPerUnitEffects
      .filter(bolusEffect => bolusEffect.isEndBgAfterPeak && !bolusEffect.hasOverlappingEffects)
      .map(bolusEffect => bolusEffect.calculateCarbsPerUnit(bgPerUnit))
    return mean(carbsPerUnits)
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getBolusAt ({ ms }) {
    return this.getAmountAt({ ms, classRef: BolusUnits })
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @param {number} options.bgPerHour
   * @param {number} options.carbPerUnit
   * @param {number} options.bgPerUnit
   * @param {number} options.bgPerCarb
   * @returns {number}
   */
  getBgAt ({
    ms,
    bgPerHour = null
  }) {
    const bolusEffects = new BolusEffects({
      items: this.getEffectsAt({ ms, classRef: BolusEffects })
    })
    const predictedEndBg = bolusEffects.items.length > 1
      ? bolusEffects.earliest?.predictedEndBg // todo: not working as effect is rendered twice, as the startBg and then over time until the end of the effect
      : bolusEffects.startBg
    if (!bolusEffects.items.length) {
      return predictedEndBg ?? this.latest?.endBg ?? this.latest?.predictedEndBg
    }
    bgPerHour = bgPerHour ?? this.calculateBgPerHour()
    const startBg = bolusEffects.earliest?.startBg

    const distanceMs = ms - startBg.startMs
    const basalAmount = bgPerHour * (distanceMs / (60 * 60 * 1000))
    const bgAmount = bolusEffects.getBgAt({ ms, startBg })
    return bgAmount + basalAmount
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getCarbsAt ({ ms }) {
    return this.getAmountAt({ ms, classRef: CarbAmount })
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getEfficacyAt ({ ms }) {
    const efficacyRatios = this.ofType(EfficacyRatio)
    const efficacyRatio = efficacyRatios.length
      ? efficacyRatios.reduce((efficacyRatio, event) => {
        return (efficacyRatio += event.amount * event.getIntensityAt({ ms }))
      }, 0) / efficacyRatios.length
      : 0
    return efficacyRatio
  }

  calculateUnits ({
    ms,
    currentBg,
    consumedCarbs,
    targetBg,
    carbsPerUnit,
    bgPerUnit,
    minimumUnits,
    hasCarbUnits,
    hasBgUnits
  } = {}) {
    const efficacyRatios = this.ofType(EfficacyRatio)
    const efficacyRatio = efficacyRatios.length
      ? efficacyRatios.reduce((efficacyRatio, event) => {
        return (efficacyRatio += event.amount)
      }, 0) / efficacyRatios.length
      : 0

    // todo: judge if currentBg is in expected range given existing effects
    //   use predicted end bg from last effect if last effect is in peak + 4 halflife

    if (bgPerUnit > 0) bgPerUnit *= -1

    const correctedCarbsPerUnit = carbsPerUnit - (carbsPerUnit * efficacyRatio)
    const correctedBgPerUnit = bgPerUnit - (bgPerUnit * efficacyRatio)

    const bgDistance = (currentBg - targetBg)
    const bgUnits = -correctedBgPerUnit ? (bgDistance / -correctedBgPerUnit) : 0
    const carbUnits = correctedCarbsPerUnit ? (consumedCarbs / correctedCarbsPerUnit) : 0

    const totalUnits = [
      hasCarbUnits && carbUnits,
      hasBgUnits && bgUnits
    ].filter(Boolean).reduce((sum, value) => sum + value, 0)
    let roundedAdjustedTotalUnits = Math.round(totalUnits / minimumUnits) * minimumUnits
    const bgPerCarb = Math.abs(correctedBgPerUnit) / correctedBgPerUnit
    const expectedBgRise = bgPerCarb * consumedCarbs
    const expectedBgFall = correctedBgPerUnit * roundedAdjustedTotalUnits
    const predictdEndBg = currentBg + expectedBgRise + expectedBgFall
    if (predictdEndBg < targetBg) {
      // always go above target instead of below
      roundedAdjustedTotalUnits -= minimumUnits
    }
    roundedAdjustedTotalUnits = Math.max(roundedAdjustedTotalUnits, 0)

    return {
      ms,
      consumedCarbs,
      currentBg,
      bgPerUnit,
      bgPerCarb,
      carbsPerUnit,
      efficacyRatio,
      bgUnits,
      carbUnits,
      totalUnits,
      roundedAdjustedTotalUnits,
      expectedBgFall,
      expectedBgRise,
      predictdEndBg
    }
  }
}
