import mergeStates from "./mergeStates"

export default function makeOnChanged(state, settings, dispatch, action, { noui = false } = {}, attrs) {
  return (name, event) => {
    let value = Object.prototype.hasOwnProperty.call(event.target, 'checked')
      ? event.target.checked
      : event.target.value
    try {
      const act = action(mergeStates(
        state,
        settings,
        noui
        ? {
          [name]: value === '' ? settings[name] : value
        }
        : {
          [name]: value === '' ? settings[name] : value,
          [`ui_${name}`]: value
        }
      ))
      Object.assign(act, attrs ?? {})
      dispatch(
        act
      )
    } catch (err) {}
  }
}
