import BgAmount from './BgAmount.js'
import DateTime from './DateTime.js'
import Day from './Day.js'
import Time from './Time.js'
import BolusEffect from './BolusEffect.js'
import BasalEffect from './BasalEffect.js'
import Effects from './Effects.js'
import MixedUnitEffects from './MixedUnitEffects.js'
import BgUnitEffects from './BgUnitEffects.js'
import CarbUnitEffects from './CarbUnitEffects.js'
import CarbEffects from './CarbEffects.js'
import BasalEffects from './BasalEffects.js'
import BgUnits from './BgUnits.js'
import CarbUnits from './CarbUnits.js'
import CarbAmount from './CarbAmount.js'
import EfficacyRatio from './EfficacyRatio.js'
import BasalRange from './BasalRange.js'
import BolusEffects from './BolusEffects.js'
import Analysis from './Analysis.js'
/** @typedef {import("./EffectProfile").default} EffectProfile */

export default class Timeline {
  /**
   * @param {Object} options
   * @param {Array<EffectProfile>} options.effectProfiles
   */
  constructor ({ effectProfiles }) {
    this.effectProfiles = effectProfiles
  }

  set effectProfiles (value) {
    this._effectProfiles = value
  }

  /** @type {[EffectProfile]} */
  get effectProfiles () {
    return this._effectProfiles
  }

  /** @type {[Amount]}]} */
  get items () {
    return (this._items = this._items || [])
  }

  order () {
    this.items.sort((a, b) => Number(a) - Number(b))
    this.dateTimes.sort((a, b) => Number(a) - Number(b))
    this.days.sort((a, b) => Number(a) - Number(b))
  }

  set effects (value) {
    this._effects = value
  }

  /** @type {Effects} */
  get effects () {
    return this._effects
  }

  /** @type {[DateTime]} */
  get dateTimes () {
    return (this._dateTimes = this._dateTimes || [])
  }

  /** @type {[Day]} */
  get days () {
    return (this._days = this._days || [])
  }

  /**
   * @param {number} ms
   * @returns {DateTime}
   */
  DateTimeFromMs (ms) {
    if (ms instanceof DateTime) return ms
    let dt = this.dateTimes.find(dt => Number(dt) === Number(ms))
    if (!dt) {
      dt = ms // new DateTime({ ms })
      this.dateTimes.push(dt)
    }
    this.DayFromMs(ms)
    return dt
  }

  /**
   * @param {number} ms
   * @returns {DateTime}
   */
  DayFromMs (ms) {
    if (ms instanceof Day) return ms
    ms = Math.floor(ms / Day.ONE_DAY) * Day.ONE_DAY
    let dt = this.days.find(dt => Number(dt) === Number(ms))
    if (!dt) {
      dt = ms // new Day({ ms })
      this.days.push(dt)
    }
    return dt
  }

  /**
   * @param {Object} options
   * @param {number} options.date
   * @param {number} options.currentBg
   * @param {number} options.carbUnits
   * @param {number} options.bgUnits
   * @param {number} options.roundedAdjustedTotalUnits
   * @param {string} options.calculationType
   * @param {number} options.consumedCarbs
   * @param {number} options.carbsPerUnit
   * @param {number} options.bgPerUnit
   * @param {number} options.minimumCarbs
   * @param {number} options.minimumUnits
   * @param {number} options.targetBg
   * @returns {Timeline}
   */
  add ({
    date,
    currentBg,
    carbUnits,
    bgUnits,
    unitAdjustmentPercentage,
    roundedAdjustedTotalUnits,
    calculationType,
    consumedCarbs,
    carbsPerUnit,
    bgPerUnit,
    minimumCarbs,
    minimumUnits,
    targetBg
  }) {
    const dateTime = this.DateTimeFromMs(date)
    const bgPerCarb = bgPerUnit / carbsPerUnit
    this.items.push(new BgAmount({ target: targetBg, amount: currentBg, startMs: dateTime }))
    const hasUnits = Boolean((calculationType === 'both' || calculationType === 'correction') && roundedAdjustedTotalUnits)
    const hasBgUnits = Boolean((calculationType === 'both' || calculationType === 'correction') && bgUnits && hasUnits)
    const hasCarbUnits = Boolean((calculationType === 'both' || calculationType === 'carbs') && carbUnits && hasUnits)
    const hasCarbs = Boolean(consumedCarbs)
    let efficacyRatio = (unitAdjustmentPercentage / 100)
    if (efficacyRatio > 0) efficacyRatio /= 2
    if (efficacyRatio < 0) efficacyRatio *= 2
    const hasEfficacyRatio = Boolean(efficacyRatio)

    if (hasBgUnits) {
      const partRatio = bgUnits / (carbUnits + bgUnits)
      this.items.push(new BgUnits({
        effectProfile: this.effectProfiles.find(p => p.name === 'bolus'),
        effectRatio: {
          bgPerUnit: -bgPerUnit,
          carbsPerUnit,
          bgPerCarb
        },
        startMs: dateTime,
        minimumAmount: minimumUnits,
        amount: roundedAdjustedTotalUnits * partRatio
      }))
    }
    if (hasCarbUnits) {
      const partRatio = carbUnits / (carbUnits + bgUnits)
      this.items.push(new CarbUnits({
        effectProfile: this.effectProfiles.find(p => p.name === 'bolus'),
        effectRatio: {
          bgPerUnit: -bgPerUnit,
          carbsPerUnit,
          bgPerCarb
        },
        startMs: dateTime,
        minimumAmount: minimumUnits,
        amount: roundedAdjustedTotalUnits * partRatio
      }))
    }
    if (hasCarbs) {
      this.items.push(new CarbAmount({
        effectProfile: this.effectProfiles.find(p => p.name === 'mostlySimpleCarbs'),
        effectRatio: {
          bgPerUnit: -bgPerUnit,
          carbsPerUnit,
          bgPerCarb
        },
        startMs: dateTime,
        minimumAmount: minimumCarbs,
        amount: consumedCarbs
      }))
    }
    if (hasEfficacyRatio) {
      this.items.push(new EfficacyRatio({
        effectProfile: this.effectProfiles.find(p => p.name === 'efficacyRatio'),
        effectRatio: {
          bgPerUnit: -bgPerUnit,
          carbsPerUnit,
          bgPerCarb
        },
        startMs: dateTime,
        minimumAmount: 0,
        amount: efficacyRatio
      }))
    }
    return this
  }

  /**
   * @param {Object} options
   * @param {string} options.durationHHmm
   * @returns {Timeline}
   */
  limit ({ durationHHmm }) {
    const durationMs = Time.fromHHmm(durationHHmm)
    const earliestMs = Number(this.dateTimes[this.dateTimes.length - 1]) - durationMs
    const clone = new Timeline({ effectProfiles: this.effectProfiles })
    clone._items = this.items.filter(r => r.startMs >= earliestMs)
    clone._dateTimes = this.dateTimes.filter(r => Number(r) >= earliestMs)
    clone._days = this.days.filter(r => Number(r) >= earliestMs)
    return clone
  }

  /**
   * @param {number} atTimeDate
   * @param {number} maxBgDistanceBeforeMs
   * @param {number} maxBgDistanceAfterMs
   * @returns {BgAmount}
   */
  findNearestBg (atTimeDate, maxBgDistanceBeforeMs, maxBgDistanceAfterMs) {
    atTimeDate = Number(atTimeDate)
    return this.items
      .filter(i => i instanceof BgAmount)
      .reduce((nearestBg, bgAmount) => {
        const bgDistance = (bgAmount.startMs - atTimeDate)
        if (bgDistance < 0 && Math.abs(bgDistance) > maxBgDistanceBeforeMs) return nearestBg
        if (bgDistance > 0 && bgDistance > maxBgDistanceAfterMs) return nearestBg
        if (!nearestBg) return bgAmount
        const currentNearestDistance = Math.abs(nearestBg.startMs - atTimeDate)
        if (Math.abs(bgDistance) < currentNearestDistance) return bgAmount
        return nearestBg
      }, null)
  }

  /**
   * @param {Object} options
   * @param {string} options.maxDurationHHmm
   * @param {string} options.maxBgBolusDistanceBeforeStartHHmm
   * @param {string} options.maxBgBolusDistanceAfterStartHHmm
   * @param {string} options.maxBgBolusDistanceBeforeEndHHmm
   * @param {string} options.maxBgBolusDistanceAfterEndHHmm
   * @param {number} options.overlappingPreviousIntensityCutoff
   * @returns {Timeline}
   */
  groupEffects ({
    maxDurationHHmm = '00:15',
    maxBgBolusDistanceBeforeStartHHmm = '00:05',
    maxBgBolusDistanceAfterStartHHmm = '00:05',
    maxBgBolusDistanceBeforeEndHHmm = '00:30',
    maxBgBolusDistanceAfterEndHHmm = '01:50',
    overlappingPreviousIntensityCutoff = 0.1
  }) {
    const maxDurationMs = Time.fromHHmm(maxDurationHHmm)
    const maxBgBolusDistanceBeforeStartMs = Time.fromHHmm(maxBgBolusDistanceBeforeStartHHmm)
    const maxBgBolusDistanceAfterStartMs = Time.fromHHmm(maxBgBolusDistanceAfterStartHHmm)
    const maxBgBolusDistanceBeforeEndMs = Time.fromHHmm(maxBgBolusDistanceBeforeEndHHmm)
    const maxBgBolusDistanceAfterEndMs = Time.fromHHmm(maxBgBolusDistanceAfterEndHHmm)
    /**
     * @param {Object} options
     * @param {Timeline} options.timeline
     * @param {Effects} options.effects
     */
    const gatherBolusEffects = ({ timeline, effects }) => {
      Effects.group({
        timeline,
        effects: timeline.items.filter(item => item instanceof BolusEffect || item instanceof EfficacyRatio || item instanceof BgAmount),
        maxDurationMs,
        onCreateGroup: groupedEffects => {
          const hasBgUnits = groupedEffects?.hasEffectType?.(BgUnits)
          const hasCarbUnits = groupedEffects?.hasEffectType?.(CarbUnits)
          const hasCarbs = groupedEffects?.hasEffectType?.(CarbAmount)
          const EffectsClass = (hasBgUnits && hasCarbUnits)
            ? MixedUnitEffects
            : hasBgUnits
              ? BgUnitEffects
              : hasCarbUnits
                ? CarbUnitEffects
                : hasCarbs
                  ? CarbEffects
                  : MixedUnitEffects
          if (!EffectsClass) return
          effects.addEffect(new EffectsClass(groupedEffects))
        }
      })
    }
    /**
     * @param {Object} options
     * @param {Timeline} options.timeline
     * @param {Effects} options.effects
     */
    const gatherBasalEffects = ({ timeline, effects }) => {
      Effects.group({
        timeline,
        effects: timeline.items.filter(item => item instanceof BasalEffect || item instanceof EfficacyRatio || item instanceof BgAmount),
        maxDurationMs,
        onCreateGroup: groupedEffects => {
          effects.addEffect(new BasalEffects(groupedEffects))
        }
      })
    }
    /**
     * @param {Object} options
     * @param {Timeline} options.timeline
     * @param {Effects} options.effects
     */
    const calculateBolusEffectOverlaps = ({ timeline, effects }) => {
      /** @type {BasalEffects} */
      let lastEffect = null
      effects.items.filter(i => i instanceof BolusEffects).forEach(effect => {
        // todo: highly inefficient but effective
        const startBg = timeline.findNearestBg(effect.startMs, maxBgBolusDistanceBeforeStartMs, maxBgBolusDistanceAfterStartMs)
        const endBg = timeline.findNearestBg(effect.endMs, maxBgBolusDistanceBeforeEndMs, maxBgBolusDistanceAfterEndMs)
        effect.startBg = startBg
        effect.endBg = endBg // can overshoot as not aware of effects
        if (!lastEffect) {
          lastEffect = effect
          return
        }
        if (lastEffect.isEffectOverlapping({ withEffect: effect, overlappingPreviousIntensityCutoff })) {
          lastEffect.addOverlappingEffect(effect)
        }
        if (Number(lastEffect.endMs) > Number(effect.startMs)) {
          // Not overlapping according to overlappingPreviousIntensityCutoff,
          //   but the lastEffect.endBg is inside the current effect
          lastEffect.endBg = effect.startBg
        }
        const isEndingBeforeLastEffect = Number(effect.endMs) < Number(lastEffect.endMs)
        if (isEndingBeforeLastEffect) return
        lastEffect = effect
      })
    }
    /**
     * @param {Object} options
     * @param {Effects} options.effects
     */
    const gatherBasalRanges = ({
      effects
    }) => {
      const basalRanges = []
      const timeline = effects.timeline
      /** @type {[BasalRange]} */
      basalRanges.length = 0
      let shouldCreateNextRange = true
      let lastBasalRange = null
      let previousBg = null
      const bolus = effects.items.filter(ev => ev instanceof BolusEffects)
      timeline.items
        .filter(i => i instanceof BgAmount)
        .forEach(bgAmount => {
          const isBgInBolusEffectEffect = bolus.some(effect => effect.isBgInEffect({ bgAmount }))
          const isBgAtBolusEffectEffectStart = bolus.some(effect => effect.isBgAtEffectStart(bgAmount))
          if ((isBgInBolusEffectEffect || isBgAtBolusEffectEffectStart) && shouldCreateNextRange) {
            previousBg = bgAmount
            return
          }
          if (shouldCreateNextRange) {
            lastBasalRange = new BasalRange({
              beforeBg: previousBg || bgAmount,
              startBg: bgAmount
            })
            shouldCreateNextRange = false
            previousBg = bgAmount
            return
          }
          if (isBgInBolusEffectEffect) {
            lastBasalRange.afterBg = bgAmount
            if (lastBasalRange.endBg) basalRanges.push(lastBasalRange)
            shouldCreateNextRange = true
            lastBasalRange = null
            previousBg = bgAmount
            return
          }
          if (isBgAtBolusEffectEffectStart) {
            lastBasalRange.addBg(bgAmount)
            lastBasalRange.afterBg = bgAmount
            basalRanges.push(lastBasalRange)
            shouldCreateNextRange = true
            lastBasalRange = null
            previousBg = bgAmount
            return
          }
          previousBg = bgAmount
          if (!lastBasalRange) return
          lastBasalRange.addBg(bgAmount)
        })
      if (lastBasalRange?.endBg) basalRanges.push(lastBasalRange)
      const basal = effects.items.filter(ev => ev instanceof BasalEffects)
      basalRanges.forEach(basalRange => {
        basal.forEach(effect => {
          if (!basalRange.isEffectOverlapping({ withEffect: effect })) return
          basalRange.addEffect(effect)
        })
        effects.addEffect(basalRange)
      })
    }
    const effects = new Effects({ timeline: this })
    this.items.sort((a, b) => a.startMs - b.startMs)
    /** @type {Effect} */
    gatherBolusEffects({ timeline: this, effects })
    gatherBasalEffects({ timeline: this, effects })
    effects.items.sort((a, b) => a.startMs - b.startMs)
    calculateBolusEffectOverlaps({ timeline: this, effects })
    effects.startMs = effects.earliest?.startMs
    effects.endMs = effects.latest?.endMs
    gatherBasalRanges({ effects })
    this.effects = effects
    return this
  }

  /**
   * @param {Object} options
   * @param {string} options.minimumDurationHHmm
   * @returns {Analysis}
   */
  analysis ({ minimumDurationHHmm = '05:00' } = {}) {
    return new Analysis({
      timeline: this,
      items: this.effects.items,
      minimumDurationHHmm
    })
  }
}
