/** @typedef {import("./BgAmount").default} BgAmount */

import Effects from './Effects.js'
import BgAmount from './BgAmount.js'
import BolusEffect from './BolusEffect.js'
import CarbAmount from './CarbAmount.js'
import EfficacyRatio from './EfficacyRatio.js'
import BolusUnits from './BolusUnits.js'
import BgUnits from './BgUnits.js'
import CarbUnits from './CarbUnits.js'

export default class BolusEffects extends Effects {
  get targetBg () {
    return (this.startBg.target + this.endBg.target) / 2
  }

  /** @type {[BolusUnits]} */
  get units () {
    return this.ofType(BolusUnits)
  }

  /** @type {[CarbAmount]} */
  get carbAmounts () {
    return this.ofType(CarbAmount)
  }

  /** @type {number} */
  get unitsTaken () {
    return this.units.reduce((sum, effect) => sum + effect.amount, 0)
  }

  /** @type {[BgUnits]} */
  get bgUnits () {
    return this.ofType(BgUnits)
  }

  /** @type {[CarbUnits]} */
  get carbUnits () {
    return this.ofType(CarbUnits)
  }

  /** @type {number} */
  get bgUnitsTaken () {
    return this.bgUnits.reduce((sum, effect) => sum + effect.amount, 0)
  }

  /** @type {number} */
  get carbUnitsTaken () {
    return this.carbUnits.reduce((sum, effect) => sum + effect.amount, 0)
  }

  /** @type {number} */
  get minimumUnits () {
    return this.units.reduce((sum, effect) => sum + effect.minimumAmount, 0) / this.units.length
  }

  /** @type {number} */
  get carbsEaten () {
    return this.carbAmounts.reduce((sum, effect) => sum + effect.amount, 0)
  }

  /** @type {boolean} */
  get hasIsolatedEffect () {
    return this.hasBgStartEnd && Boolean(!this.overlappingEffects?.length)
  }

  /**
   * @param {Object} options
   * @param {BgAmount} options.bgAmount
   * @param {number} options.overlappingPreviousIntensityCutoff
   * @returns
   */
  isBgInEffect ({ bgAmount, overlappingPreviousIntensityCutoff }) {
    return this.isMsInEffect({ ms: bgAmount.startMs, overlappingPreviousIntensityCutoff })
  }

  /**
   * @param {BgAmount} bgAmount
   * @returns {number}
   */
  isBgAtEffectStart (bgAmount) {
    return (Number(bgAmount.startMs) === Number(this.startMs))
  }

  getBgAt ({
    ms,
    startBg = this.startBg
  }) {
    if (this.isMsBeforeRange(ms)) return startBg
    const startAmount = startBg.amount
    const efficacyRatios = this.ofType(EfficacyRatio)
    const efficacyRatio = efficacyRatios.length
      ? efficacyRatios.reduce((efficacyRatio, event) => {
        return (efficacyRatio += event.amount * event.getPassedIntensityAt({ ms }))
      }, 0) / efficacyRatios.length
      : 0
    const bgAmount = this.ofType(BolusEffect).reduce((bgAmount, event) => {
      const effectPassedRatio = event.getPassedIntensityAt({ ms })
      const effectAmount = event.amount * effectPassedRatio
      if (event instanceof BgUnits) {
        const bgPerUnitCorrected = event.effectRatio.bgPerUnit - (event.effectRatio.bgPerUnit * efficacyRatio)
        return bgAmount + (bgPerUnitCorrected * effectAmount)
      }
      if (event instanceof CarbUnits) {
        const bgPerUnitCorrected = event.effectRatio.bgPerUnit - (event.effectRatio.bgPerUnit * efficacyRatio)
        return bgAmount + (bgPerUnitCorrected * effectAmount)
      }
      if (event instanceof CarbAmount) {
        const bgPerUnitCorrected = event.effectRatio.bgPerUnit - (event.effectRatio.bgPerUnit * efficacyRatio)
        const carbsPerUnitCorrected = event.effectRatio.carbsPerUnit - (event.effectRatio.carbsPerUnit * efficacyRatio)
        const bgPerCarbCorrected = Math.abs(bgPerUnitCorrected) / carbsPerUnitCorrected
        return bgAmount + (bgPerCarbCorrected * effectAmount)
      }
      return bgAmount
    }, startAmount)
    return new BgAmount({ amount: bgAmount, startMs: ms, target: null })
  }

  get predictedEndBg () {
    return this.getBgAt({ ms: this.endMs })
  }
}
