import BasalUnits from './BasalUnits.js'
import Effects from './Effects.js'
import Time from './Time.js'
/** @typedef {import("./BgAmount").default} Bg */
/** @typedef {import("./BasalEffect").default} BasalEffect */

// TODO: cleaup unnecessary stuff

export default class BasalRange extends Effects {
  constructor ({
    beforeBg,
    startBg
  }) {
    super({ startMs: startBg.ms })
    this.beforeBg = beforeBg
    this.addBg(startBg)
  }

  /** @type {BgAmount} */
  set beforeBg (value) {
    this._beforeBg = value
  }

  /** @type {BgAmount} */
  get beforeBg () {
    return this._beforeBg
  }

  set startBg (value) {
    this.startMs = value.startMs
    this._startBg = value
  }

  /** @type {BgAmount} */
  get startBg () {
    return this._startBg
  }

  set endBg (value) {
    this.endMs = value.startMs
    this._endBg = value
  }

  /** @type {BgAmount} */
  get endBg () {
    return this._endBg
  }

  /** @type {BgAmount} */
  set afterBg (value) {
    this._afterBg = value
  }

  /** @type {BgAmount} */
  get afterBg () {
    return this._afterBg
  }

  /** @type {BgAmount} */
  get bgAmounts () {
    return (this._bg = this._bg || [])
  }

  /**
   * @param {BgAmount} bgAmount
   */
  addBg (bgAmount) {
    if (!this.bgAmounts.length) this.startBg = bgAmount
    this.bgAmounts.push(bgAmount)
    this.endBg = bgAmount
  }

  /** @type {[Effect]} */
  get items () {
    return (this._items = this._items || [])
  }

  /** @param {Effect} effect */
  addEffect (effect) {
    this.items.push(effect)
  }

  /**
   * @param {Object} options
   * @param {BasalEffect} options.withEffect
   */
  isEffectOverlapping ({ withEffect }) {
    const effects = [this, { withEffect }]
    effects.sort((a, b) => Number(a.endMs) - Number(b.endMs))
    const [before, after] = effects
    const isOutsideRight = (Number(after.startMs) >= Number(before.endMs))
    if (isOutsideRight) return false
    return true
  }

  /** @type {number} */
  get bgPerHour () {
    const duration = (this.endMs - this.startMs) / Time.ONE_HOUR
    const distance = this.endBg - this.startBg
    return distance / duration
  }

  /** @type {[BasalUnits]} */
  get units () {
    return this.items.flatMap(effect => effect.ofType(BasalUnits))
  }

  /** @type {number} */
  get configuredUnitsPerDose () {
    const { units } = this
    return units.reduce((sum, effect) => sum + effect.amount, 0) / units.length
  }
}
