/** @typedef {import("./Effect").default} Effect */
/** @typedef {import("./Timeline").default} Timeline */
/** @typedef {import("./BgAmount").default} BgAmount */
import DateTimeRange from './DateTimeRange.js'

export default class Effects extends DateTimeRange {
  /**
   * @param {Object} options
   * @param {Timeline} options.timeline
   * @param {[Effects]|[Effect]} items
   * @param {number} startMs
   * @param {number} endMs
   */
  constructor ({ timeline, items, startMs, endMs }) {
    super({ startMs, endMs })
    this.timeline = timeline
    this._items = items
    if (items && !startMs && !endMs) {
      this.startMs = this.earliest?.startMs
      this.endMs = this.latest?.endMs
      this.startBg = this.earliest?.startBg
      this.endBg = this.latest?.endBg
    }
  }

  set timeline (value) {
    this._timeline = value
  }

  /** @type {Timeline} */
  get timeline () {
    return this._timeline
  }

  set startBg (value) {
    this._startBg = value
  }

  /** @type {BgAmount} */
  get startBg () {
    return this._startBg
  }

  set endBg (value) {
    this._endBg = value
  }

  /** @type {BgAmount} */
  get endBg () {
    return this._endBg
  }

  /** @type {boolean} */
  get hasBgStartEnd () {
    return Boolean(this.startBg && this.endBg)
  }

  /** @type {boolean} */
  hasEffectType (classRef) {
    if (!classRef && this.items.length) return true
    return this.items.some(ev => ev instanceof classRef)
  }

  /** @type {[Effects|Effect]} */
  get items () {
    return (this._items = this._items || [])
  }

  /** @type {Effects|Effect} */
  get earliest () {
    return this.items.reduce((latest, effect) => {
      if (!latest) return effect
      if (effect.startMs < latest.startMs) return effect
      return latest
    }, null)
  }

  /** @type {Effects|Effect} */
  get latest () {
    return this.items.reduce((latest, effect) => {
      if (!latest) return effect
      if (effect.endMs > latest.endMs) return effect
      return latest
    }, null)
  }

  /**
   * @param {Function} classRef
   * @returns {[Effects]|[Effect]}
   */
  ofType (classRef) {
    const hasParents = this.hasEffectType(Effects)
    const hasChildrenOfClass = this.hasEffectType(classRef)
    if (hasParents && !hasChildrenOfClass) {
      const items = this.items.flatMap(effect => effect.ofType(classRef))
      return [...new Set(items)]
    }
    if (!hasChildrenOfClass) {
      return []
    }
    const items = this.items.filter(item => item instanceof classRef)
    return [...new Set(items)]
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @param {Function} options.classRef
   * @returns {[Effects]}
   */
  getEffectsAt ({ ms, classRef = null }) {
    if (!this.isMsInRange(ms)) return []
    return this.ofType(classRef).filter(effects => effects.isMsInRange(ms))
  }

  /**
   * @param {Object} options
   * @param {ms} options.ms
   * @param {Function} options.classRef
   * @returns {number}
   */
  getAmountAt ({ ms, classRef = null }) {
    if (!this.isMsInRange(ms)) {
      return 0
    }
    return this
      .ofType(classRef)
      .filter(effects => effects.isMsInRange(ms))
      .reduce((amount, effect) => {
        return amount + effect.getAmountAt({ ms })
      }, 0)
  }

  /**
   * @param {Effect} effect
   */
  addEffect (effect) {
    this.items.push(effect)
  }

  /** @type {Array<Effects|Effect>} */
  get overlappingEffects () {
    return (this._overlappingEffects = this._overlappingEffects || [])
  }

  /** @type {boolean} */
  get hasOverlappingEffects () {
    return Boolean(this.overlappingEffects.length)
  }

  /**
   * @param {Effect} effect
   */
  addOverlappingEffect (effect) {
    if (this.overlappingEffects.includes(effect)) return this
    this.overlappingEffects.push(effect)
    effect.overlappingEffects.push(this)
    return this
  }

  /**
   * @param {Object} options
   * @param {Effect} options.withEffect
   * @param {number} options.overlappingPreviousIntensityCutoff
   */
  isEffectOverlapping ({ withEffect, overlappingPreviousIntensityCutoff }) {
    const effects = [this, withEffect]
    effects.sort((a, b) => Number(a.endMs) - Number(b.endMs))
    const [before, after] = effects
    const isOutsideRight = (Number(after.startMs) >= Number(before.endMs))
    if (isOutsideRight) return false
    const afterStartsInsideBefore = (Number(after.startMs) >= Number(before.startMs) && Number(after.startMs) <= Number(before.endMs))
    if (!afterStartsInsideBefore) return true
    const beforeRemainingIntensity = before.latest.getRemainingIntensityAt({ ms: after.startMs })
    if (beforeRemainingIntensity <= overlappingPreviousIntensityCutoff) return false
    return true
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @param {number} options.overlappingPreviousIntensityCutoff
   */
  isMsInEffect ({ ms, overlappingPreviousIntensityCutoff = null }) {
    const isInside = (Number(ms) > Number(this.startMs) && Number(ms) <= Number(this.endMs))
    if (!isInside) return false
    if (overlappingPreviousIntensityCutoff === null) return true
    const remainingIntensity = this.latest.getRemainingIntensityAt({ ms })
    if (remainingIntensity <= overlappingPreviousIntensityCutoff) return false
    return true
  }

  /**
   * @param {number} ms
   */
  isMsAtEffectStart (ms) {
    return (Number(ms) === Number(this.startMs))
  }

  /** @type {number} */
  get peakEnd () {
    return this.items
      .filter(effect => typeof effect.peakEnd === 'number')
      .reduce((lastPeakEnd, effect) => {
        const peakEnd = effect.peakEnd
        if (lastPeakEnd > peakEnd) return lastPeakEnd
        return peakEnd
      }, null)
  }

  /** @type {number} */
  get isEndBgAfterPeak () {
    return Boolean(this.endBg && this.isMsAfterPeak(this.endBg?.startMs))
  }

  /**
   * @param {number} ms
   */
  isMsAfterPeak (ms) {
    const { peakEnd } = this
    if (peakEnd === null) return false
    return (ms >= peakEnd)
  }

  /**
   * @param {object} object
   * @param {[Effect]} object.effects
   * @param {number} maxDurationMs
   * @param {Function} object.onCreateGroup
   */
  static group ({ timeline, effects, maxDurationMs, onCreateGroup }) {
    const createGroup = group => {
      group.endMs = group.latest.endMs
      onCreateGroup(group)
    }
    let lastGroup = null
    effects.forEach(effect => {
      const { startMs } = effect
      const isNotInLastGroup = (!lastGroup || startMs < lastGroup.startMs || startMs > lastGroup.startMs + maxDurationMs)
      if (isNotInLastGroup) {
        if (lastGroup) createGroup(lastGroup)
        lastGroup = new Effects({
          timeline,
          startMs
        })
      }
      lastGroup.addEffect(effect)
    })
    if (lastGroup) createGroup(lastGroup)
  }
}
