import BolusEffects from './BolusEffects.js'

export default class CarbEffects extends BolusEffects {
  calculateBgPerCarb () {
    const { carbsEaten, endBg, startBg } = this
    const actualBgDiff = (endBg - startBg)
    if (carbsEaten === 0) return null
    const bgPerCarb = actualBgDiff / carbsEaten
    return bgPerCarb
  }
}
