import DateTimeRange from './DateTimeRange.js'

export default class Amount extends DateTimeRange {
  /**
  * @param {Object} options
  * @param {number} options.amount
  * @param {number} options.startMs
  * @param {number} options.endMs
  */
  constructor ({ amount, startMs, endMs }) {
    super({ startMs, endMs })
    this.amount = amount
  }

  set amount (value) {
    this._amount = value
  }

  /** @type {number} */
  get amount () {
    return this._amount
  }

  [Symbol.toPrimitive] (hint) {
    if (hint === 'number' || hint === 'default') {
      return this.amount
    }
    return String(this.amount)
  }
}
