import BolusEffects from './BolusEffects.js'

export default class MixedUnitEffects extends BolusEffects {
  /** @type {boolean} */
  get isBgUnitsLessThanMinimumUnits () {
    return Math.abs(this.bgUnitsTaken) < this.minimumUnits
  }

  /** @type {boolean} */
  get isCarbUnitsLessThanMinimumUnits () {
    return Math.abs(this.carbUnitsTaken) < this.minimumUnits
  }

  get configuredBgPerUnit () {
    const { bgUnits } = this
    const totalRatio = bgUnits.reduce((total, effect) => total + effect.effectRatio.bgPerUnit, 0)
    return totalRatio / bgUnits.length
  }

  get configuredCarbsPerUnit () {
    const { carbUnits } = this
    const totalRatio = carbUnits.reduce((total, effect) => total + effect.effectRatio.carbsPerUnit, 0)
    return totalRatio / carbUnits.length
  }

  calculateBgPerUnit () {
    const { carbUnitsTaken, bgUnitsTaken, endBg, startBg, configuredBgPerUnit } = this

    const expectedEndBg = this.getBgAt(endBg.startMs)

    console.log(endBg.amount, expectedEndBg.amount)

    // what action did we take
    const actionedBgCorrectionDrop = bgUnitsTaken * (configuredBgPerUnit * -1)
    const actionedBgCarbDrop = carbUnitsTaken * (configuredBgPerUnit * -1)
    const actionedBgDiff = actionedBgCarbDrop - actionedBgCorrectionDrop
    // what was the measured bg difference
    const measuredBgDiff = (endBg - startBg)
    // recalculate the ratio
    const calculatedAdjustmentRatio = actionedBgDiff / measuredBgDiff
    const newBgPerUnit = (bgUnitsTaken * calculatedAdjustmentRatio)
    return newBgPerUnit
  }

  calculateCarbsPerUnit () {
    const { carbsEaten, carbUnitsTaken, bgUnitsTaken, endBg, startBg } = this

    const expectedEndBg = this.getBgAt({
      ms: endBg.startMs,
      startBg
    })

    console.log('calculateCarbsPerUnit mixed', endBg.amount, expectedEndBg.amount)

    // what action did we take
    // const actionedBgCorrectionDrop = bgUnitsTaken * (configuredBgPerUnit * -1)
    // const actionedBgCarbDrop = carbUnitsTaken * (configuredBgPerUnit * -1)
    const actionedBgDiff = (expectedEndBg - startBg) // actionedBgCarbDrop - actionedBgCorrectionDrop
    // what was the measured bg difference
    const measuredBgDiff = (endBg - startBg)

    console.log(startBg, endBg, expectedEndBg, actionedBgDiff, measuredBgDiff)
    // recalculate the ratio
    const calculatedAdjustmentRatio = actionedBgDiff / measuredBgDiff
    const newCarbsPerUnit = (carbUnitsTaken * calculatedAdjustmentRatio) / carbsEaten
    return newCarbsPerUnit
  }
}
