import Amount from './Amount.js'
/** @typedef {import("./EffectProfile").default} EffectProfile */

export default class Effect extends Amount {
  /**
   * @param {Object} options
   * @param {number} options.amount
   * @param {number} options.startMs
   * @param {EffectProfile} options.effectProfile
   * @param {Object} options.effectRatio
   * @param {number} options.minimumAmount
   */
  constructor ({ amount, startMs, effectProfile, effectRatio, minimumAmount }) {
    super({
      startMs,
      endMs: startMs + effectProfile.endMs,
      amount
    })
    this.minimumAmount = minimumAmount
    // effectRatios for moving bgAmount are not applied at profile but at the (carbs/units) per record
    this.effectRatio = effectRatio
    this.effectProfile = effectProfile
  }

  set effectProfile (value) {
    this._effectProfile = value
  }

  /** @returns {EffectProfile} */
  get effectProfile () {
    return this._effectProfile
  }

  set minimumAmount (value) {
    this._minimumAmount = value
  }

  /** @type {number} */
  get minimumAmount () {
    return this._minimumAmount
  }

  set effectRatio (value) {
    this._effectRatio = value
  }

  /** @type {Object} */
  get effectRatio () {
    return this._effectRatio
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getRemainingIntensityAt ({ ms = Date.now() }) {
    if (!this.isMsInRange(ms)) return 0
    const atMs = ms - this.startMs
    return this.effectProfile.getRemainingIntensityAt({ ms: atMs })
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getPassedIntensityAt ({ ms = Date.now() }) {
    if (this.isMsBeforeRange(ms)) return 0
    if (this.isMsAfterRange(ms)) return 1
    const atMs = ms - this.startMs
    return this.effectProfile.getPassedIntensityAt({ ms: atMs })
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getIntensityAt ({ ms = Date.now() }) {
    if (!this.isMsInRange(ms)) return 0
    const atMs = ms - this.startMs
    return this.effectProfile.getIntensityAt({ ms: atMs })
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {number}
   */
  getAmountAt ({ ms = Date.now() }) {
    if (!this.isMsInRange(ms)) return 0
    const intensity = this.getIntensityAt({ ms })
    const amount = intensity * this.amount
    return amount
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {boolean}
   */
  isMsBeforePeakEnd ({ ms = Date.now() }) {
    return (ms < this.peakEnd)
  }

  /**
   * @param {Object} options
   * @param {number} options.ms
   * @returns {boolean}
   */
  isMsAfterPeakEnd ({ ms = Date.now() }) {
    return !this.isMsBeforePeakEnd({ ms })
  }

  /** @type {number} */
  get peakEnd () {
    return this.effectProfile.peakEnd + this._startMs
  }
}
