export default class Time {
  /**
   * @param {Object} options
   * @param {number} options.ms
   */
  constructor ({ ms = -1, str }) {
    this.ms = ms
    // this.str = str ?? Time.toHHmm(ms)
  }

  set ms (value) {
    this._ms = value
  }

  /** @type {number} */
  get ms () {
    return this._ms
  }

  [Symbol.toPrimitive] (hint) {
    if (hint === 'number' || hint === 'default') {
      return this.ms
    }
    return this.str
  }

  /** @type {number} */
  static get ONE_HOUR () {
    return (this._ONE_HOUR = this._ONE_HOUR ?? 60 * 60 * 1000)
  }

  /** @type {number} */
  static get ONE_MINUTE () {
    return (this._ONE_MINUTE = this._ONE_MINUTE ?? 60 * 1000)
  }

  static fromHHmm (HHmm) {
    if (HHmm instanceof Time) return HHmm
    if (!HHmm) return 0
    if (!HHmm.includes(':')) {
      return new Time({ str: HHmm })
    }
    const [hoursString, minutesString] = HHmm.split(':')
    const totalHours = parseInt(hoursString)
    const totalMinutes = parseInt(minutesString)
    const ms = (totalHours * Time.ONE_HOUR) + (totalMinutes * Time.ONE_MINUTE)
    return ms // new Time({ ms })
  }

  static toHHmm (ms) {
    const pad = HHmm => {
      if (HHmm.length === 1) HHmm = `00:0${HHmm}`
      if (HHmm.length === 2) HHmm = `00:${HHmm}`
      if (HHmm.length === 4) HHmm = `0${HHmm}`
      return HHmm
    }
    const date = new Date(ms)
    const hours = (date / Time.ONE_HOUR)
    const wholeHours = Math.floor(hours)
    const remainingMs = (hours - wholeHours) * Time.ONE_HOUR
    const minutes = Math.floor(remainingMs / Time.ONE_MINUTE)
    return pad(`${String(wholeHours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`)
  }
}
